SELECT d.*, c.cycle_type AS cycleType, c.cycle_day AS cycleDay, c.deadline_days AS deadlineDays, c.urge_days AS urgeDays, COALESCE(p.periodCount, 0) AS periodCount, COALESCE(m.memberCount, 0) AS memberCount FROM flow_dispatch d LEFT JOIN flow_dispatch_config c ON c.task_id = d.id LEFT JOIN ( SELECT task_id, COUNT(*) AS periodCount FROM flow_task_dispatch GROUP BY task_id ) p ON p.task_id = d.id LEFT JOIN ( SELECT task_id, COUNT(*) AS memberCount FROM flow_task_member GROUP BY task_id ) m ON m.task_id = d.id
AND d.task_name LIKE CONCAT('%', #{taskName}, '%')
AND d.status = #{status}
AND d.is_sample = #{sample}
AND d.creator_name LIKE CONCAT('%', #{creatorName}, '%')
AND d.create_time >= #{createStart}
AND d.create_time <= CONCAT(#{createEnd}, ' 23:59:59')
AND (d.is_sample = 1 OR d.dept_id = #{deptId})
ORDER BY d.create_time DESC, d.id DESC LIMIT #{offset}, #{limit}

